sys_script_client.script:
function onSubmit() {
    var desc = g_form.getValue('short_description');
    if (!desc || desc.length < 10) {
        g_form.addErrorMessage('Short description must be at least 10 characters.');
        return false;
    }
    var severity = g_form.getValue('severity');
    if (severity === '1') {
        var component = g_form.getValue('affected_component');
        if (!component) {
            g_form.addErrorMessage('Affected component is required for Critical severity issues.');
            return false;
        }
    }
    return true;
}
